"""Render the catalogs, tiers and recipes as the Skill's generated reference pages.

``render_all`` returns ``{relative path: text}`` for ``skill/chemdraw/references``. Each
layer gets one short guide that a reader loads first, plus size-bounded shards with the
long member lists, so an agent reads only the part it needs.
"""

from __future__ import annotations

import json
from typing import Any, Iterable

from . import classify, recipes as recipe_module

SHARD_BYTES = 45_000
BANNER = (
    "> Generated by `cdx.py regen-catalog` from the catalogs in `cdxml_toolkit/catalog/data`. Do not hand-edit.\n"
)
TIER_LINE = "{TIERS}"  # replaced by the classification's own wording in render_all


def _text(*lines: str) -> str:
    return "\n".join(lines).rstrip("\n") + "\n"


def _cell(value: Any) -> str:
    return str(value if value not in (None, "") else "").replace("|", "\\|").replace("\n", " ")


def _tier_counts(summary: dict[str, int]) -> str:
    return ", ".join(f"{tier} {summary[tier]}" for tier in classify.TIERS)


def _shards(prefix: str, blocks: list[tuple[str, str]], intro: str) -> dict[str, str]:
    """Pack ``(title, body)`` blocks into numbered shards of about ``SHARD_BYTES``."""
    shards: list[list[tuple[str, str]]] = [[]]
    size = 0
    for title, body in blocks:
        weight = len(body.encode("utf-8"))
        if shards[-1] and size + weight > SHARD_BYTES:
            shards.append([])
            size = 0
        shards[-1].append((title, body))
        size += weight
    pages = {}
    for number, group in enumerate(shards, 1):
        names = ", ".join(title for title, _ in group)
        header = _text(f"# {intro} (part {number} of {len(shards)})", "", BANNER, f"Contents: {names}.", "")
        pages[f"inventory/{prefix}-{number}.md"] = header + "\n" + "\n".join(body for _, body in group)
    return pages


def _shard_links(prefix: str, pages: dict[str, str], base: str = "") -> list[str]:
    links = []
    for name in sorted(pages):
        if name.startswith(f"inventory/{prefix}-"):
            first = next(line for line in pages[name].splitlines() if line.startswith("Contents:"))
            links.append(f"- [{name.split('/')[-1]}]({base}{name}): {first[len('Contents: '):]}")
    return links


# ----------------------------------------------------------------------------- ChemScript

def _chemscript(rows, catalog, summary) -> tuple[str, list[tuple[str, str]]]:
    by_type: dict[str, list[dict[str, Any]]] = {}
    for row in rows:
        if row["layer"] == "chemscript" and "." in row["symbol"]:
            by_type.setdefault(row["symbol"].split(".")[0], []).append(row)
    api = [t for t in catalog["types"] if t["role"] == "api"]
    other = [t for t in catalog["types"] if t["role"] != "api"]

    table = ["| Type | Base | Members | T2 | Summary |", "| --- | --- | ---: | ---: | --- |"]
    blocks = []
    for entry in api:
        members = by_type.get(entry["name"], [])
        verified = sum(row["tier"] == "T2" for row in members)
        table.append(
            f"| {entry['name']} | {_cell(entry.get('base'))} | {len(members)} | {verified} | {_cell(entry.get('doc'))} |"
        )
        lines = [f"## {entry['name']}", ""]
        if entry.get("base") in {t["name"] for t in api}:
            lines.append(f"Inherits the members of `{entry['base']}`.")
            lines.append("")
        for row in members:
            mark = f" **{row['tier']}**" if row["tier"] != "T3" else ""
            overloads = f" ×{row['overloads']}" if row.get("overloads", 1) > 1 else ""
            doc = f" — {row['doc']}" if row.get("doc") else ""
            recipe = f" (recipe `{row['recipe']}`)" if row.get("recipe") else ""
            lines.append(f"- `{row['symbol'].split('.', 1)[1]}` {row['kind']}{overloads}{mark}{recipe}{doc}")
        lines.append("")
        blocks.append((entry["name"], "\n".join(lines)))

    counts = catalog["counts"]
    guide = _text(
        "# ChemScript SDK Interface Catalog",
        "",
        BANNER,
        f"Installed SDK `{catalog['assembly']}` {catalog['assembly_version']}, verified on {catalog['verified_on']}.",
        f"{counts['types']} types ({counts['types_api']} API, {counts['types_collection']} collection wrappers, "
        f"{counts['types_interop']} interop); {counts['members_total']} members, of which {counts['members_listed']} "
        f"belong to API types and {counts['api_members_documented']} have a summary in the SDK's own documentation.",
        "",
        "## Reaching it",
        "",
        "- `inspect_chemscript_sdk` reflects the installed assembly and prints exact signatures; filter by `type_name` or `query`.",
        "- `execute_chemscript_sdk` runs a declarative program (`construct`, `call_static`, `call`, `get`, `set`, `get_index`, "
        "`iterate`, `dispose`, `release`); file access, overwrite and unsafe interop stay off unless the task needs them.",
        "- Verified programs are in [recipes-chemdraw.md](recipes-chemdraw.md). Windows reads the installed SDK; macOS answers "
        "an emulated subset of the core classes ([operations.md](operations.md)).",
        "- Members of a base type are available on its subtypes: `StructureData` and `ReactionData` inherit `ChemicalData`.",
        "",
        f"Tiers: {TIER_LINE} Members: {_tier_counts(summary)}.",
        "",
        "## API types",
        "",
        *table,
        "",
        "## Types that are counted, not listed",
        "",
        "Collection wrappers are reached through a property of their owner; interop types are plumbing and are never exposed.",
        "",
        *[f"- `{t['name']}` ({t['role']}, {t.get('member_count', 0)} members)" for t in other],
        "",
        "## Member lists",
        "",
    )
    return guide, blocks


# ----------------------------------------------------------------------------- COM

def _com_parameter(parameter: dict[str, Any]) -> str:
    return f"{parameter['name']}{'?' if parameter.get('optional') else ''}"


def _com_member_line(type_name: str, member: dict[str, Any], rows_by_id) -> str:
    row = rows_by_id.get(f"com:{type_name}.{member['name']}")
    mark = f" **{row['tier']} `{row['tool']}`**" if row and row["tier"] != "T3" else ""
    doc = f" — {member['doc']}" if member.get("doc") else ""
    hidden = " (hidden)" if member.get("hidden") else ""
    kind = member["kind"]
    if kind == "method":
        arguments = ", ".join(_com_parameter(p) for p in member.get("parameters", []))
        return f"- `{member['name']}({arguments})` → {member['returns']}{hidden}{mark}{doc}"
    if kind == "property":
        indexed = f"[{', '.join(p['name'] for p in member['parameters'])}]" if member.get("parameters") else ""
        return f"- `{member['name']}{indexed}` property {'/'.join(member['access'])} : {member['type']}{hidden}{mark}{doc}"
    if kind == "constant":
        return f"- `{member['name']}` = {member['value']}{doc}"
    return f"- `{member['name']}` {kind} : {member.get('type', '')}{hidden}{mark}{doc}"


def _com(rows, catalog, summary) -> tuple[str, list[tuple[str, str]], list[tuple[str, str]]]:
    rows_by_id = {row["id"]: row for row in rows if row["layer"] == "com"}
    library = catalog["object_library"]
    control_only = [t for t in catalog["control_library"]["types"] if t["name"] not in {x["name"] for x in library["types"]}]
    interfaces = [t for t in library["types"] if t["kind"] in ("dispatch", "interface") and t.get("members")]
    members_blocks = []
    table = ["| Interface | Members | Summary |", "| --- | ---: | --- |"]
    for entry in interfaces:
        table.append(f"| {entry['name']} | {len(entry['members'])} | {_cell(entry.get('doc'))} |")
        lines = [f"## {entry['name']}", ""]
        lines += [_com_member_line(entry["name"], member, rows_by_id) for member in entry["members"]]
        lines.append("")
        members_blocks.append((entry["name"], "\n".join(lines)))
    enums = [t for t in library["types"] if t["kind"] == "enum"]
    classes = [t for t in library["types"] if t["kind"] == "coclass"]
    value_blocks = []
    for entry in enums:
        lines = [f"## {entry['name']}", ""] + [_com_member_line(entry["name"], m, rows_by_id) for m in entry["members"]] + [""]
        value_blocks.append((entry["name"], "\n".join(lines)))
    if classes:
        lines = ["## Classes", ""] + [f"- `{c['name']}` creates {', '.join(c['implements'])}" for c in classes] + [""]
        value_blocks.append(("Classes", "\n".join(lines)))

    counts = catalog["counts"]
    guide = _text(
        "# ChemDraw COM Interface Catalog",
        "",
        BANNER,
        f"Read from the type libraries inside `ChemDraw.exe` and `ChemDrawCtl.dll` of ChemDraw, verified on {catalog['verified_on']}; "
        "reading them does not start ChemDraw.",
        f"Object library `{library['library']}`: {counts['object_library_types']} types, {counts['object_library_members']} members. "
        f"Control library: {counts['control_library_types']} types, {counts['control_library_members']} members, "
        f"{len(control_only)} types not in the object library.",
        "",
        "## Reaching it",
        "",
        "- `ChemDraw.Application` is the root: `Documents` → `Document` → `Objects` and the typed collections "
        "(`Atoms`, `Bonds`, `Graphics`, `Tables`, `PlasmidMaps`, ...). `MenuBars` exposes the menus ([interface-menu.md](interface-menu.md)).",
        "- `chemdraw_com_call` (Windows) calls any member that is not blocked; T1 members have a dedicated tool such as "
        "`convert_cdx_cdxml` or `render_to_png`, T2 members a recipe in [recipes-chemdraw.md](recipes-chemdraw.md), and all "
        "other members are documented here so that nothing is guessed.",
        "- Run native work through the tools: they take the shared ChemDraw lock and use a private instance.",
        "",
        f"Tiers: {TIER_LINE} Rows: {_tier_counts(summary)}.",
        "",
        "## Interfaces",
        "",
        *table,
        "",
        "## Types only in the control library",
        "",
        *[f"- `{t['name']}` ({t['kind']}, {len(t.get('members', []))} members)" for t in control_only],
        "",
        "## Member lists",
        "",
    )
    return guide, members_blocks, value_blocks


# ----------------------------------------------------------------------------- menu

def _menu(rows, catalog, summary) -> str:
    rows_by_id = {row["id"]: row for row in rows if row["layer"] == "menu"}
    counts = catalog["counts"]
    lines = [
        "# ChemDraw Menu Command Catalog",
        "",
        BANNER,
        f"Read from the menus of a running ChemDraw, verified on {catalog['verified_on']}: {counts['menus']} menus, "
        f"{counts['commands']} commands with an id, {counts['popups']} sub-menus or dialog-only entries.",
        "",
        "The id is the `CommandID` that `IChemOfficeMenuItem.Execute` takes through COM. A command acts on the current "
        "selection, and whether it is enabled depends on that selection, so a list of enabled commands is not part of the catalog.",
        "No tool runs menu commands on Windows, because ChemDraw runs them only from a visible window; on macOS "
        "`Clean Up Structure` and `Convert Name to Structure` run through the application menu (see [operations.md](operations.md)).",
        "",
        f"Tiers: {TIER_LINE} Rows: {_tier_counts(summary)}.",
        "",
    ]
    for menu in catalog["menus"]:
        lines += [f"## {menu['caption']}", ""]
        if not menu["items"]:
            lines += ["Empty in a default installation (add-ins register here).", ""]
            continue
        for item in menu["items"]:
            row = rows_by_id[f"menu:{menu['caption']}/{item['caption']}"]
            mark = f" **{row['tier']} `{row['tool']}`**" if row["tier"] != "T3" else ""
            detail = "sub-menu" if item.get("popup") else f"id {item['command_id']}"
            lines.append(f"- {item['caption']} — {detail}{mark}")
        lines.append("")
    return _text(*lines)


# ----------------------------------------------------------------------------- CDXML

def _cdxml(rows, catalog, summary) -> tuple[str, list[tuple[str, str]]]:
    rows_by_id = {row["id"]: row for row in rows if row["layer"] == "cdxml"}
    table = ["| Element | Evidence | Tier | Tool | Occurrences | Parents |", "| --- | --- | --- | --- | ---: | --- |"]
    blocks = []
    for element in catalog["elements"]:
        row = rows_by_id[f"cdxml:{element['name']}"]
        table.append(
            f"| `{element['name']}` | {_cell(', '.join(element['evidence']) or 'none')} | {row['tier']} | "
            f"{_cell(row.get('tool'))} | {element.get('count', '')} | {_cell(', '.join(element.get('parents', [])))} |"
        )
        if "attributes" not in element:
            continue
        lines = [f"## {element['name']}", ""]
        if element.get("children"):
            lines += [f"Children: {', '.join(f'`{c}`' for c in element['children'])}.", ""]
        for attribute in element["attributes"]:
            shape = attribute["kind"]
            if attribute["kind"] == "enum":
                shape = "one of " + ", ".join(f"`{v}`" for v in attribute["values"])
            lines.append(f"- `{attribute['name']}` {shape} ({attribute['count']} uses in {attribute['documents']} documents)")
        lines.append("")
        blocks.append((element["name"], "\n".join(lines)))

    counts = catalog["counts"]
    guide = _text(
        "# CDXML Document Model Catalog",
        "",
        BANNER,
        f"ChemDraw ships no DTD, so this model is empirical, verified on {catalog['verified_on']}. "
        f"It scans {catalog['documents_scanned']} CDXML documents that ChemDraw installs or wrote itself (templates, samples, its "
        f"conversion of the bundled CDX files, and {sum(f['status'] == 'ok' for f in catalog['fixtures'])} objects built through COM), "
        "and checks the remaining names of the format against ChemDraw's binaries. Absence from this list proves nothing.",
        f"{counts['elements']} elements: {counts['elements_observed']} observed, {counts['elements_binary_only']} found only in the binaries, "
        f"{counts['elements_unconfirmed']} without evidence; {counts['attributes']} attributes.",
        "",
        "Evidence: `observed` the element appears in documents ChemDraw wrote; `binary` the name occurs in ChemDraw's own files "
        "but in no observed document; `none` a name of the format this installation gave no evidence for.",
        "Attribute values are summarised by shape (integer, number, numbers, a short list of values), never by document text. "
        "Preserve attributes you do not understand when editing a document.",
        "",
        f"Tiers: {TIER_LINE} Rows: {_tier_counts(summary)}.",
        "",
        "## Elements",
        "",
        *table,
        "",
        "## Attributes",
        "",
    )
    return guide, blocks


# ----------------------------------------------------------------------------- recipes

def _recipes(recipes: list[dict[str, Any]]) -> str:
    lines = [
        "# ChemDraw Interface Recipes",
        "",
        BANNER,
        "Each recipe is a program for a generic tool, run on the installed ChemDraw with its results checked. "
        "A catalog row is tiered T2 only when a recipe here covers it.",
        "",
    ]
    for recipe in recipes:
        lines += [
            f"## {recipe['title']}",
            "",
            f"`{recipe['id']}` · tool `{recipe['tool']}` · verified on {recipe['verified_on']} · platforms {', '.join(recipe['platforms'])}",
            "",
            "Covers: " + ", ".join(f"`{symbol}`" for symbol in recipe["members"]) + ".",
            "",
            "Program (the `program` argument):",
            "",
            "```json",
            "[",
            ",\n".join("  " + json.dumps(step, ensure_ascii=False) for step in recipe["program"]),
            "]",
            "```",
            "",
            "Checked results:",
            "",
        ]
        for item in recipe["expect"]:
            wanted = ", ".join(f"{k} {v!r}" for k, v in item.items() if k != "step")
            lines.append(f"- step {item['step']}: {wanted}")
        lines.append("")
    return _text(*lines)


# ----------------------------------------------------------------------------- all

def render_all(
    catalogs: dict[str, dict[str, Any]] | None = None,
    recipes: list[dict[str, Any]] | None = None,
    classification: dict[str, Any] | None = None,
) -> dict[str, str]:
    catalogs = catalogs or {layer: classify.load_catalog(layer) for layer in classify.LAYERS}
    recipes = recipes if recipes is not None else recipe_module.load()
    classification = classification or classify.load_classification()
    rows = classify.classify(catalogs, recipes, classification)
    summary = classify.summarize(rows)
    pages: dict[str, str] = {}

    guide, blocks = _chemscript(rows, catalogs["chemscript"], summary["chemscript"])
    shards = _shards("chemscript", blocks, "ChemScript SDK members")
    pages.update(shards)
    pages["interface-chemscript.md"] = guide + _text(*_shard_links("chemscript", shards))

    guide, member_blocks, value_blocks = _com(rows, catalogs["com"], summary["com"])
    shards = _shards("com", member_blocks, "ChemDraw COM members")
    shards.update(_shards("com-values", value_blocks, "ChemDraw COM enumerations and classes"))
    pages.update(shards)
    pages["interface-com.md"] = guide + _text(*_shard_links("com", shards))

    pages["interface-menu.md"] = _menu(rows, catalogs["menu"], summary["menu"])

    guide, blocks = _cdxml(rows, catalogs["cdxml"], summary["cdxml"])
    shards = _shards("cdxml-attributes", blocks, "CDXML element attributes")
    pages.update(shards)
    pages["interface-cdxml-model.md"] = guide + _text(*_shard_links("cdxml-attributes", shards))

    pages["recipes-chemdraw.md"] = _recipes(recipes)
    tiers = classification["tiers"]
    wording = "Tiers: " + " ".join(f"**{tier}** {tiers[tier]}" for tier in classify.TIERS)
    return {
        name: text.replace(f"Tiers: {TIER_LINE}", wording)
        for name, text in sorted(pages.items())
    }
